```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT trace_id, span_id, time ct, duration cd FROM abnormal_traces WHERE service_name='search' AND attr_span_kind='Client' AND span_name='geo.Geo/Nearby'), s AS (SELECT trace_id, parent_span_id, time st, duration sd FROM abnormal_traces WHERE service_name='geo' AND attr_span_kind='Server'), j AS (SELECT c.*, s.st, s.sd, (epoch(s.st)-epoch(c.ct))*1000 start_gap_ms FROM c JOIN s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id) SELECT count(*) pairs, round(approx_quantile(cd,0.5)/1e6,1) client_p50_ms, round(approx_quantile(sd,0.5)/1e6,3) geo_server_p50_ms, round(approx_quantile(start_gap_ms,0.5),1) gap_p50_ms FROM j",
          "claim": "search's client span to geo takes about 1585 ms p50, but geo's server span takes 0.14 ms; the gap is before geo starts."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,2) p50_ms, round(approx_quantile(duration,0.95)/1e6,2) p95_ms FROM normal_traces WHERE service_name='search' AND span_name IN ('geo.Geo/Nearby','rate.Rate/GetRates','search.Search/Nearby') GROUP BY 1,2",
          "claim": "In the normal period, search's geo.Geo/Nearby client span had p50 about 0.4 ms, so the abnormal slowdown is a clear change."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name IN ('HTTP /hotels','search.Search/Nearby')) OR (service_name='search' AND span_name='search.Search/Nearby') GROUP BY 1,2",
          "claim": "Frontend's /hotels and its search.Search/Nearby call both reach about 1.6 s p50, matching search's own slow server span."
        }
      ]
    }
  ]
}
```

